package com.linbit.linstor.logging;

import com.linbit.linstor.core.LinStor;

import java.io.File;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.TimeZone;

import edu.umd.cs.findbugs.annotations.SuppressFBWarnings;
import org.junit.After;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;

public class ErrorReportPagingTest
{
    // deliberately use a log-dir that is not used by any other test in order to avoid reading ErrorReports
    // that were generated by other unit tests.
    private static final String TEST_LOG_DIR = "build/test-logs/errorreportpaging";

    private StdErrorReporter errReporter;

    // cleanup-method, doesn't matter if the dir existed and was deleted or didn't exist in the first place
    @SuppressFBWarnings("RV_RETURN_VALUE_IGNORED_BAD_PRACTICE")
    private void deleteDirectory(File directoryToBeDeleted)
    {
        File[] allContents = directoryToBeDeleted.listFiles();
        if (allContents != null)
        {
            for (File file : allContents)
            {
                deleteDirectory(file);
            }
        }
        directoryToBeDeleted.delete();

        Assert.assertFalse("Directory still exists", Files.exists(directoryToBeDeleted.toPath()));
    }

    @Before
    public void setUp() throws Exception
    {
        deleteDirectory(Paths.get(TEST_LOG_DIR).toFile());
        errReporter = new StdErrorReporter(
            LinStor.CONTROLLER_MODULE,
            Paths.get(TEST_LOG_DIR),
            false,
            "testnode",
            "INFO",
            "INFO"
        );
        errReporter.reportError(new IllegalStateException("state exc"));
        // keep the error-times distinct so that time-based sort assertions are deterministic
        Thread.sleep(10);
        errReporter.reportError(new NullPointerException());
        Thread.sleep(10);
        errReporter.reportError(new RuntimeException("runtime exc"));
    }

    @After
    public void tearDown() throws Exception
    {
        errReporter.shutdown();
    }

    private ErrorReportResult list(
        Long limit,
        Long offset,
        ErrorReportSortBy sortBy,
        Boolean sortAsc
    )
    {
        return errReporter.listReports(false, null, null, Collections.emptySet(), limit, offset, sortBy, sortAsc);
    }

    private static List<String> exceptions(ErrorReportResult result)
    {
        List<String> ret = new ArrayList<>();
        for (ErrorReport report : result.getErrorReports())
        {
            ret.add(report.getException().orElse(null));
        }
        return ret;
    }

    @Test
    public void testSortByException()
    {
        ErrorReportResult asc = list(null, null, ErrorReportSortBy.EXCEPTION, true);
        Assert.assertEquals(3, asc.getTotalCount());
        Assert.assertEquals(
            List.of("IllegalStateException", "NullPointerException", "RuntimeException"),
            exceptions(asc)
        );

        ErrorReportResult desc = list(null, null, ErrorReportSortBy.EXCEPTION, false);
        Assert.assertEquals(
            List.of("RuntimeException", "NullPointerException", "IllegalStateException"),
            exceptions(desc)
        );
    }

    @Test
    public void testOffsetAndLimit()
    {
        ErrorReportResult page = list(1L, 1L, ErrorReportSortBy.EXCEPTION, true);
        // the total count must not be affected by the paging
        Assert.assertEquals(3, page.getTotalCount());
        Assert.assertEquals(List.of("NullPointerException"), exceptions(page));

        ErrorReportResult rest = list(10L, 2L, ErrorReportSortBy.EXCEPTION, true);
        Assert.assertEquals(3, rest.getTotalCount());
        Assert.assertEquals(List.of("RuntimeException"), exceptions(rest));

        ErrorReportResult beyond = list(10L, 5L, ErrorReportSortBy.EXCEPTION, true);
        Assert.assertEquals(3, beyond.getTotalCount());
        Assert.assertTrue("Expected an empty page", beyond.getErrorReports().isEmpty());
    }

    @Test
    public void testNullsSortedFirst()
    {
        // the NullPointerException has no exception message, so it must be sorted first
        ErrorReportResult asc = list(null, null, ErrorReportSortBy.EXCEPTION_MESSAGE, true);
        Assert.assertEquals("NullPointerException", asc.getErrorReports().get(0).getException().orElse(null));

        // ... and last for descending sort
        ErrorReportResult desc = list(null, null, ErrorReportSortBy.EXCEPTION_MESSAGE, false);
        Assert.assertEquals("NullPointerException", desc.getErrorReports().get(2).getException().orElse(null));
    }

    @Test
    public void testSortByFilenameMatchesReportSequence()
    {
        ErrorReportResult asc = list(null, null, ErrorReportSortBy.FILENAME, true);
        Assert.assertEquals(
            List.of("IllegalStateException", "NullPointerException", "RuntimeException"),
            exceptions(asc)
        );
        List<String> fileNames = new ArrayList<>();
        for (ErrorReport report : asc.getErrorReports())
        {
            fileNames.add(report.getFileName());
        }
        List<String> sorted = new ArrayList<>(fileNames);
        Collections.sort(sorted);
        Assert.assertEquals(sorted, fileNames);
    }

    @Test
    public void testDefaultSortIsTimeDescending()
    {
        // without explicit sort parameters the reports are sorted by error-time descending,
        // which for these reports is the reverse of the report sequence
        ErrorReportResult dflt = errReporter.listReports(false, null, null, Collections.emptySet(), null, null);
        Assert.assertEquals(3, dflt.getTotalCount());
        Assert.assertEquals("RuntimeException", dflt.getErrorReports().get(0).getException().orElse(null));
        Assert.assertEquals("IllegalStateException", dflt.getErrorReports().get(2).getException().orElse(null));
    }

    @Test
    public void testErrorTimeIsIndependentOfTheSystemZone() throws Exception
    {
        // the report header is rendered in UTC; on hosts not running in UTC the stored instant used to be
        // shifted by the host's UTC offset, which also broke since/to filtering
        TimeZone defaultZone = TimeZone.getDefault();
        try
        {
            TimeZone.setDefault(TimeZone.getTimeZone("Etc/GMT-8"));
            long before = System.currentTimeMillis();
            errReporter.reportError(new IllegalArgumentException("zone exc"));
            long after = System.currentTimeMillis();

            ErrorReportResult result = list(null, null, ErrorReportSortBy.EXCEPTION, true);
            ErrorReport report = result.getErrorReports().stream()
                .filter(rpt -> "IllegalArgumentException".equals(rpt.getException().orElse(null)))
                .findFirst()
                .orElseThrow();
            long stored = report.getDateTime().toEpochMilli();
            Assert.assertTrue(
                "stored error time " + stored + " is not within [" + before + ", " + after + "]",
                stored >= before - 1000 && stored <= after + 1000
            );
        }
        finally
        {
            TimeZone.setDefault(defaultZone);
        }
    }
}
